import{_ as o,o as d,c,a0 as s}from"./chunks/framework.BdekkmWZ.js";const h=JSON.parse('{"title":"Pinia 官方库 (Vapor) 与 Pinia by UTS (VDOM) 双模式自动匹配实现计划","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/plans/2026-09-14-pinia-vapor-vdom-adaptive-store.md","filePath":"superpowers/plans/2026-09-14-pinia-vapor-vdom-adaptive-store.md"}'),i={name:"superpowers/plans/2026-09-14-pinia-vapor-vdom-adaptive-store.md"};function r(t,e,a,n,l,p){return d(),c("div",null,[...e[0]||(e[0]=[s('<h1 id="pinia-官方库-vapor-与-pinia-by-uts-vdom-双模式自动匹配实现计划" tabindex="-1">Pinia 官方库 (Vapor) 与 Pinia by UTS (VDOM) 双模式自动匹配实现计划 <a class="header-anchor" href="#pinia-官方库-vapor-与-pinia-by-uts-vdom-双模式自动匹配实现计划" aria-label="Permalink to &quot;Pinia 官方库 (Vapor) 与 Pinia by UTS (VDOM) 双模式自动匹配实现计划&quot;">​</a></h1><blockquote><p><strong>面向 AI 代理的工作者：</strong> 必需子技能：使用 superpowers:subagent-driven-development（推荐）或 superpowers:executing-plans 逐任务实现此计划。步骤使用复选框（<code>- [ ]</code>）语法来跟踪进度。</p></blockquote><p><strong>目标：</strong> 在 <code>src/store</code> 中构建双模式自动匹配架构，在 App 蒸汽模式（Vapor）、Web、小程序、iOS/鸿蒙平台自动使用官方 <code>pinia</code> 3.0.4 + <code>pinia-plugin-persistedstate</code> 4.7.1，在 Android VDOM 模式自动使用 <code>Pinia by uts</code> (<code>x-pinia-s</code>)，对所有业务页面暴露一致的调用接口。</p><p><strong>架构：</strong></p><ul><li><code>src/store/vapor/</code>：存放基于官方 Pinia 与 <code>pinia-plugin-persistedstate</code> 的组合式实现（<code>index.ts</code>, <code>app.ts</code>, <code>user.ts</code>, <code>token.ts</code>）；</li><li><code>src/store/vdom/</code>：存放 Android VDOM 专用的 <code>x-pinia-s</code> class 风格实现（<code>index.uts</code>, <code>app.uts</code>, <code>user.uts</code>, <code>token.uts</code>）；</li><li><code>src/store/index.uts</code>：统一门面层通过条件编译指令（<code>#ifdef APP-ANDROID &amp;&amp; !VUE3-VAPOR</code> / <code>#ifndef APP-ANDROID &amp;&amp; !VUE3-VAPOR</code>）自动匹配并重导出对应实现与所有 stores。</li></ul><p><strong>技术栈：</strong> uni-app X, UTS, Vue 3, Pinia 3.0.4, pinia-plugin-persistedstate 4.7.1, x-pinia-s.</p><hr><h2 id="涉及文件与职责" tabindex="-1">涉及文件与职责 <a class="header-anchor" href="#涉及文件与职责" aria-label="Permalink to &quot;涉及文件与职责&quot;">​</a></h2><ul><li><strong>创建：</strong> <code>src/store/vdom/index.uts</code>、<code>app.uts</code>、<code>user.uts</code>、<code>token.uts</code> — 封装 Android VDOM (x-pinia-s) 模式实现。</li><li><strong>创建：</strong> <code>src/store/vapor/index.ts</code>、<code>app.ts</code>、<code>user.ts</code>、<code>token.ts</code> — 封装官方 Pinia (Vapor / Web / iOS / Harmony / 小程序) 模式实现。</li><li><strong>修改：</strong> <code>src/store/index.uts</code> — 统一入口条件编译自动分发。</li><li><strong>移除：</strong> 移除冗余的 <code>src/store/app.uts</code>、<code>user.uts</code>、<code>token.uts</code>，由 <code>index.uts</code> 单点分发，避免双份维护。</li><li><strong>规格参考：</strong> <code>docs/superpowers/specs/2026-09-14-pinia-vapor-vdom-adaptive-store-design.md</code></li></ul><hr><h2 id="任务列表" tabindex="-1">任务列表 <a class="header-anchor" href="#任务列表" aria-label="Permalink to &quot;任务列表&quot;">​</a></h2><h3 id="任务-1-整理并归档-android-vdom-实现-src-store-vdom" tabindex="-1">任务 1：整理并归档 Android VDOM 实现 (<code>src/store/vdom/</code>) <a class="header-anchor" href="#任务-1-整理并归档-android-vdom-实现-src-store-vdom" aria-label="Permalink to &quot;任务 1：整理并归档 Android VDOM 实现 (`src/store/vdom/`)&quot;">​</a></h3><ul><li>[x] <strong>步骤 1：创建 <code>src/store/vdom/</code> 目录并将现有代码移入</strong><ul><li><code>src/store/vdom/index.uts</code>：Pinia 实例与持久化插件</li><li><code>src/store/vdom/app.uts</code>：<code>AppStore</code> 类及 <code>useAppStore</code></li><li><code>src/store/vdom/user.uts</code>：<code>UserStore</code> 类及 <code>useUserStore</code></li><li><code>src/store/vdom/token.uts</code>：<code>TokenStore</code> 类及 <code>useTokenStore</code></li></ul></li></ul><hr><h3 id="任务-2-实现官方-pinia-模块-src-store-vapor" tabindex="-1">任务 2：实现官方 Pinia 模块 (<code>src/store/vapor/</code>) <a class="header-anchor" href="#任务-2-实现官方-pinia-模块-src-store-vapor" aria-label="Permalink to &quot;任务 2：实现官方 Pinia 模块 (`src/store/vapor/`)&quot;">​</a></h3><ul><li>[x] <strong>步骤 1：创建 <code>src/store/vapor/index.ts</code></strong><ul><li>初始化 <code>createPinia()</code></li><li>配置 <code>piniaPluginPersistedstate</code> 配合 <code>uni.getStorageSync</code> / <code>uni.setStorageSync</code></li><li>调用 <code>setActivePinia(pinia)</code></li></ul></li><li>[x] <strong>步骤 2：创建 <code>src/store/vapor/app.ts</code></strong><ul><li>定义与导出 <code>IAppState</code></li><li>使用 <code>defineStore</code> 实现 <code>useAppStore</code>，返回包含 <code>state</code> 响应式对象及 actions（<code>setTheme</code>, <code>setThemeMode</code>, <code>initThemeMode</code>, <code>refreshIsDark</code>, <code>setLocale</code>）</li><li>开启 <code>persist: true</code>（key 为 <code>pinia:app</code>）</li></ul></li><li>[x] <strong>步骤 3：创建 <code>src/store/vapor/user.ts</code></strong><ul><li>定义与导出 <code>IUserInfo</code>, <code>IUserState</code></li><li>使用 <code>defineStore</code> 实现 <code>useUserStore</code>，包含 <code>state.userInfo</code> 与 actions（<code>setUserInfo</code>, <code>setAvatar</code>, <code>clearUserInfo</code>）</li><li>开启 <code>persist: true</code>（key 为 <code>pinia:user</code>）</li></ul></li><li>[x] <strong>步骤 4：创建 <code>src/store/vapor/token.ts</code></strong><ul><li>定义与导出 <code>ILoginForm</code>, <code>ISingleTokenRes</code>, <code>IDoubleTokenRes</code>, <code>ITokenState</code></li><li>使用 <code>defineStore</code> 实现 <code>useTokenStore</code>，包含 <code>state</code> 与 actions（<code>setSingleToken</code>, <code>setDoubleToken</code>, <code>clearToken</code>, <code>getToken</code>, <code>isTokenValid</code>, <code>isRefreshTokenValid</code>, <code>hasLoginInfo</code>, <code>hasValidLogin</code>）</li><li>开启 <code>persist: true</code>（key 为 <code>pinia:token</code>）</li></ul></li></ul><hr><h3 id="任务-3-构建单一门面层条件编译分发-src-store-index-uts" tabindex="-1">任务 3：构建单一门面层条件编译分发 (<code>src/store/index.uts</code>) <a class="header-anchor" href="#任务-3-构建单一门面层条件编译分发-src-store-index-uts" aria-label="Permalink to &quot;任务 3：构建单一门面层条件编译分发 (`src/store/index.uts`)&quot;">​</a></h3><ul><li>[x] <strong>步骤 1：重构 <code>src/store/index.uts</code></strong><ul><li><code>#ifdef APP-ANDROID &amp;&amp; !VUE3-VAPOR</code> 导入并导出 <code>vdom</code></li><li><code>#ifndef APP-ANDROID &amp;&amp; !VUE3-VAPOR</code> 导入并导出 <code>vapor</code></li></ul></li><li>[x] <strong>步骤 2：删除冗余的 <code>src/store/app.uts</code>、<code>user.uts</code>、<code>token.uts</code></strong><ul><li>全局统一从 <code>src/store</code> 导入，消灭重复代码和重复条件判断</li></ul></li></ul><hr><h3 id="任务-4-语法检查、红线自检与验证" tabindex="-1">任务 4：语法检查、红线自检与验证 <a class="header-anchor" href="#任务-4-语法检查、红线自检与验证" aria-label="Permalink to &quot;任务 4：语法检查、红线自检与验证&quot;">​</a></h3><ul><li>[x] <strong>步骤 1：运行 <code>npm run lint</code></strong><ul><li>确保 0 错误</li></ul></li><li>[x] <strong>步骤 2：校验规范文档更新与提交 Git</strong><ul><li>规范文档已更新，代码已提交</li></ul></li></ul><hr><h2 id="验证结论" tabindex="-1">验证结论 <a class="header-anchor" href="#验证结论" aria-label="Permalink to &quot;验证结论&quot;">​</a></h2><ul><li><code>npm run lint</code> 验证 0 errors。</li><li>业务调用端完全零改造，API 100% 兼容。</li></ul>',25)])])}const m=o(i,[["render",r]]);export{h as __pageData,m as default};
